package org.schoolkernel.workspace;

import static org.junit.jupiter.api.Assertions.*;
import java.util.List;
import com.microsoft.playwright.APIResponse;
import com.microsoft.playwright.options.RequestOptions;
import org.junit.jupiter.api.Test;
import tools.jackson.databind.JsonNode;
import tools.jackson.databind.node.ObjectNode;

/** Explicit hard-policy targets, all matching intersections and immutable exact source fidelity. */
class DefinitionRoomPoliciesBrowserIT extends WorkbenchBrowserSupport {
    @Test
    void browserAllowedTeacherScopeHomeTargetsIncompleteCorrectionAndRestart(){
        initial();open();policies();JsonNode source=draft().path("sourceDocument").deepCopy(),nativeBefore=definition().deepCopy();reference("subjectId").fill("math");assertEquals("mathematics-room-policy",page().locator("#room-policy-id").inputValue());page().locator("#room-policy-id").fill("Policy.ID_9");page().locator("#room-policy-teacher-mode").selectOption("selected");reference("teacherId").fill("teacher-alex");room("room-101").check();save();assertEquals(JSON.readTree("{\"id\":\"Policy.ID_9\",\"subjectId\":\"math\",\"teacherId\":\"teacher-alex\",\"allowedRoomIds\":[\"room-101\"]}"),policy("Policy.ID_9"));effects();workbench.awaitText("Hard room intersection: [\"room-101\"]");assertEquals(nativeBefore.path("lessons"),definition().path("lessons"));assertEquals(source,draft().path("sourceDocument"));
        page().locator("#room-policy-target-mode").selectOption("home");save();assertTrue(policy("Policy.ID_9").path("useHomeRoom").booleanValue());assertFalse(policy("Policy.ID_9").has("allowedRoomIds"));assertEquals(4,policy("Policy.ID_9").size());assertTrue(draft().path("issues").toString().contains("declare a home room"));assertFalse(definition().path("cohorts").get(0).has("homeRoomId"));workbench.awaitText("requires this class to declare a home room");
        page().locator("#room-policy-target-mode").selectOption("incomplete");save();assertFalse(policy("Policy.ID_9").has("useHomeRoom"));assertFalse(policy("Policy.ID_9").has("allowedRoomIds"));assertTrue(draft().path("issues").toString().contains("exactly one target"));page().locator("#room-policy-target-mode").selectOption("allowed");room("room-101").check();page().locator("#room-policy-teacher-mode").selectOption("any");save();assertFalse(policy("Policy.ID_9").has("teacherId"));assertFalse(draft().path("issues").toString().contains("BLOCKING"));
        page().locator("#add-room-policy").click();assertEquals("",page().locator("#room-policy-subjectId").inputValue());reference("subjectId").fill("science");room("room-101").check();save();assertEquals(2,definition().path("roomAssignments").size());assertEquals("science-room-policy",policy("science-room-policy").path("id").asString());String saved=storedDocument();workbench.reload();policies();assertEquals(saved,storedDocument());try(var restarted=startRestartableWorkspace()){int p=((org.springframework.boot.web.server.context.WebServerApplicationContext)restarted).getWebServer().getPort();workbench.open(p);policies();assertEquals(saved,storedDocument());}
    }
    @Test
    void hardIntersectionsCapacityCapabilitiesAvailabilityLocksCuratorAndInvalidFields(){
        initial();open();policies();ObjectNode a=item("first");a.putArray("allowedRoomIds").add("room-101").add("room-102");assertEquals(200,command("",a,null).status());ObjectNode b=item("second");b.put("teacherId","teacher-alex").putArray("allowedRoomIds").add("room-102");assertEquals(200,command("",b,null).status());assertFalse(draft().path("issues").toString().contains("BLOCKING"));
        ObjectNode c=item("third");c.putArray("allowedRoomIds").add("room-101");assertEquals(200,command("",c,null).status());assertTrue(draft().path("issues").toString().contains("no room in common"));c.putArray("allowedRoomIds").add("room-102");assertEquals(200,command("third",c,null).status());assertFalse(draft().path("issues").toString().contains("BLOCKING"));
        ObjectNode doc=((ObjectNode)storedWorkspaceDocument()).deepCopy();ObjectNode def=doc.withObject("definitionDraft").withObject("definition");((ObjectNode)def.path("lessons").get(0)).put("periodLock","mon-1").put("roomLock","room-101").putArray("requiredRoomCapabilityIds").add("lab");((ObjectNode)def.path("rooms").get(1)).put("capacity",0).putArray("availablePeriodIds");store("DEFINITION_DRAFT",doc);assertEquals(200,command("first",a,null).status());String issues=draft().path("issues").toString();assertTrue(issues.contains("persistent room lock"));assertTrue(issues.contains("sufficient capacity"));assertTrue(issues.contains("No matched policy room is available"));assertEquals("room-101",definition().path("lessons").get(0).path("roomLock").asString());
        doc=((ObjectNode)storedWorkspaceDocument()).deepCopy();def=doc.withObject("definitionDraft").withObject("definition");((ObjectNode)def.path("subjects").get(0)).put("curatorLesson",true);((ObjectNode)def.path("cohorts").get(0)).put("curatorTeacherId","teacher-alex").put("homeRoomId","room-101");store("DEFINITION_DRAFT",doc);assertEquals(200,command("first",a,null).status());assertTrue(draft().path("issues").toString().contains("contradict the curator home room"));
        ObjectNode invalid=item("invalid");invalid.put("teacherId","missing").put("useHomeRoom",false).putArray("allowedRoomIds").add("missing-room").add("missing-room");assertEquals(200,command("",invalid,null).status());assertEquals(invalid,policy("invalid"));issues=draft().path("issues").toString();assertTrue(issues.contains("exactly one target"));assertTrue(issues.contains("explicitly true"));assertTrue(issues.contains("Duplicate reference"));assertTrue(issues.contains("missing-room"));assertTrue(issues.contains("teacherId"));
        invalid=item("invalid");invalid.putArray("allowedRoomIds");assertEquals(200,command("invalid",invalid,null).status());assertTrue(draft().path("issues").toString().contains("empty target"));invalid.withArray("allowedRoomIds").add("room-101");assertEquals(200,command("invalid",invalid,null).status());assertFalse(draft().path("issues").toString().contains("RoomAssignment\",\"ownerId\":\"invalid"));doc=((ObjectNode)storedWorkspaceDocument()).deepCopy();def=doc.withObject("definitionDraft").withObject("definition");((ObjectNode)def.path("rooms").get(1)).put("capabilityIds",false).put("availablePeriodIds",false).put("capacity","unfinished");store("DEFINITION_DRAFT",doc);workbench.reload();policies();effects();workbench.awaitText("Hard room intersection");assertFalse(definition().path("rooms").get(1).path("capabilityIds").booleanValue());assertEquals("unfinished",definition().path("rooms").get(1).path("capacity").asString());
    }
    @Test
    void sourceCurrentCatalogIdentityUnsupportedStateAndCsrfNeverMutate(){
        storeAccepted(fixtures.validAcceptedDocument());workbench.open();open();policies();workbench.awaitText("require scheduling catalog 9");assertEquals(0,page().locator("#room-policy-form").count());String unchanged=storedDocument();ObjectNode item=item("policy");item.putArray("allowedRoomIds").add("room-101");assertEquals(409,command("",item,null).status());assertEquals(unchanged,storedDocument());
        ObjectNode doc=((ObjectNode)storedWorkspaceDocument()).deepCopy();doc.withObject("definitionDraft").withObject("definition").put("catalogVersion",9);store("DEFINITION_DRAFT",doc);workbench.reload();policies();JsonNode source=draft().path("sourceDocument").deepCopy();assertEquals(200,command("",item,null).status());assertEquals(source,draft().path("sourceDocument"));for(var row:source.properties())assertEquals(row.getValue(),storedWorkspaceDocument().path(row.getKey()));unchanged=storedDocument();assertEquals(409,command("",item,null).status());assertEquals(unchanged,storedDocument());assertEquals(409,command("policy",item.deepCopy().put("id","new"),null).status());assertEquals(unchanged,storedDocument());assertEquals(400,command("policy",item.deepCopy().put("displayName","Not supported"),null).status());assertEquals(unchanged,storedDocument());
        APIResponse csrf=page().request().post(base()+"/api/definition-draft/room-policies",RequestOptions.create().setData("{}").setHeader("Content-Type","application/json").setHeader("Origin",base()).setHeader("If-Match","\"ws-"+storedVersion()+"\""));assertEquals(403,csrf.status());assertEquals(unchanged,storedDocument());for(WorkspaceState state:WorkspaceState.values()){if(state==WorkspaceState.DEFINITION_DRAFT)continue;store(state.name(),storedWorkspaceDocument());unchanged=storedDocument();assertEquals(409,command("policy",item,null).status());assertEquals(unchanged,storedDocument());}
    }
    @Test
    void responsiveWorkingRetentionStaleMergeConflictStorageTransportAndNavigation() throws Exception {
        initial();open();policies();reference("subjectId").fill("math");room("room-101").check();save();String id=definition().path("roomAssignments").get(0).path("id").asString();ObjectNode saved=((ObjectNode)policy(id)).deepCopy();page().locator("#room-policy-teacher-mode").selectOption("selected");reference("teacherId").fill("teacher-alex");String before=storedDocument();for(int width:List.of(1600,1280,390,700)){workbench.viewport(width,844);workbench.expect("document.documentElement.scrollWidth <= innerWidth");assertEquals(before,storedDocument());if(width<=700)assertEquals(0,page().locator("#room-policy-form").count());}workbench.viewport(1280,800);assertEquals("teacher-alex",page().locator("#room-policy-teacherId").inputValue());nav("Review");page().locator("#school-stay").click();assertEquals("teacher-alex",page().locator("#room-policy-teacherId").inputValue());
        saved.putArray("allowedRoomIds").add("room-102");assertEquals(200,command(id,saved,null).status());String newer=storedDocument();page().locator("#save-room-policy").click();workbench.awaitText("No change was committed");assertEquals(newer,storedDocument());page().locator("#room-policy-refresh").click();workbench.expect("document.querySelector('#room-policy-form') && document.querySelector('#room-policy-teacherId').value === 'teacher-alex' && [...document.querySelectorAll('#room-policy-form input[type=checkbox]')].some(n=>n.getAttribute('aria-label').endsWith('(room-102)') && n.checked)");save();assertEquals(JSON.readTree("[\"room-102\"]"),policy(id).path("allowedRoomIds"));assertEquals("teacher-alex",policy(id).path("teacherId").asString());
        reference("subjectId").fill("science");saved=((ObjectNode)policy(id)).deepCopy().put("subjectId","missing");assertEquals(200,command(id,saved,null).status());page().locator("#save-room-policy").click();workbench.awaitText("No change was committed");page().locator("#room-policy-refresh").click();workbench.awaitText("Newer saved fields conflict");assertTrue(page().locator("#save-room-policy").isDisabled());page().getByRole(com.microsoft.playwright.options.AriaRole.BUTTON,new com.microsoft.playwright.Page.GetByRoleOptions().setName("Keep my reviewed conflicting values").setExact(true)).click();String storageBefore=storedDocument();withRejectedWorkspaceUpdates("NEW.lifecycle_state = 'DEFINITION_DRAFT'",()->{page().locator("#save-room-policy").click();workbench.awaitText("No change was committed");assertEquals(storageBefore,storedDocument());assertEquals("science",page().locator("#room-policy-subjectId").inputValue());});page().route("**/api/definition-draft/room-policies",route->route.abort());page().locator("#save-room-policy").click();workbench.awaitText("No change was committed");assertEquals(storageBefore,storedDocument());page().unroute("**/api/definition-draft/room-policies");nav("Review");page().locator("#school-save-continue").click();workbench.expect("document.querySelector('#authoring-section h3')?.textContent === 'Review'");assertEquals("science",policy(id).path("subjectId").asString());
    }
    private void initial(){ObjectNode definition=((ObjectNode)fixtures.validAcceptedDocument().path("acceptedBaseline").path("definition")).deepCopy().put("catalogVersion",9);ObjectNode doc=JSON.createObjectNode();doc.set("initialDefinition",definition);store("INITIAL_DRAFT",doc);workbench.open();}
    private com.microsoft.playwright.Page page(){return workbench.page();}
    private void open(){page().locator("#open-authoring").click();page().locator("#confirm-authoring").click();workbench.awaitText("Saved school-definition draft");}
    private void nav(String section){page().locator("button[data-section='"+section+"']").click();}
    private void policies(){nav("Room policies");if(draft().path("definition").path("catalogVersion").intValue()>=9)page().locator("#room-policy-form").waitFor();}
    private void effects(){var group=page().locator(".definition-saved-detail").first();if(group.count()>0&&!"true".equals(group.evaluate("node=>String(node.open)")))group.locator("summary").click();}
    private com.microsoft.playwright.Locator reference(String field){var input=page().locator("#room-policy-"+field);var details=input.locator("xpath=ancestor::details").first();if(details.count()>0&&!"true".equals(details.evaluate("node=>String(node.open)")))details.locator("summary").first().click();return input;}
    private com.microsoft.playwright.Locator room(String id){return page().locator("input[aria-label$='("+id+")']");}
    private void save(){long version=storedVersion();page().locator("#save-room-policy").click();workbench.expect("document.querySelector('#school-save-status')?.textContent.startsWith('Saved —')");assertEquals(version+1,storedVersion());}
    private JsonNode draft(){return storedWorkspaceDocument().path("definitionDraft");}
    private JsonNode definition(){return draft().path("definition");}
    private JsonNode policy(String id){for(JsonNode row:definition().path("roomAssignments"))if(id.equals(row.path("id").asString()))return row;fail("Missing "+id);return null;}
    private ObjectNode item(String id){return JSON.createObjectNode().put("id",id).put("subjectId","math");}
    private String base(){return "http://localhost:"+port;}
    private APIResponse command(String originalId,JsonNode item,String version){ObjectNode body=JSON.createObjectNode().put("originalId",originalId);body.set("item",item);JsonNode csrf=JSON.readTree(page().request().get(base()+"/api/csrf").text());return page().request().post(base()+"/api/definition-draft/room-policies",RequestOptions.create().setData(JSON.writeValueAsString(body)).setHeader("Content-Type","application/json").setHeader("Origin",base()).setHeader("If-Match",version==null?"\"ws-"+storedVersion()+"\"":version).setHeader(csrf.path("headerName").asString(),csrf.path("token").asString()));}
    private void store(String state,JsonNode document){jdbc.sql("UPDATE workspace_aggregate SET lifecycle_state=:state, version=version+1, active_run_id=NULL, document=CAST(:document AS jsonb) WHERE workspace_id=1").param("state",state).param("document",JSON.writeValueAsString(document)).update();}
}
